import{_ as i,l,o as a,c as n,v as o,p as d,x as t,d as r,i as s,S as f}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"文件锁","description":"","frontmatter":{"title":"文件锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/file-locking.md","filePath":"cs/file-locking.md","lastUpdated":1789023840000}'),p={name:"cs/file-locking.md"};function h(_,e,E,S,m,u){const c=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="文件锁" tabindex="-1">文件锁 <a class="header-anchor" href="#文件锁" aria-label="Permalink to &quot;文件锁&quot;">​</a></h1><div class="epigraph"><p>建议锁只约束自愿调用 flock/fcntl 的进程；强制锁让普通 read/write 也会 EAGAIN。两者都不替代应用自己的协议。</p><footer>—— 据 POSIX fcntl 锁；McKusick 对 BSD flock 的讨论；Linux <code>fcntl(2)</code> 对 OFD 锁的整理</footer></div><p><a href="/cs/nfs-semantics">上一课</a>已点名远程上锁更难。本地也不是「文件自带互斥」：<a href="/cs/file-bytestream">字节流</a> 默认可同时写。缺口是 <strong>文件锁</strong>：整文件 <code>flock</code>、字节范围 <code>fcntl</code>、打开文件描述锁（OFD），以及它们与 <a href="/cs/vfs">VFS</a> 的关系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个编辑器写同一文件，页缓存共帧，内容交错。锁提供劝告：<code>F_WRLCK</code> 互斥，<code>F_RDLCK</code> 共享。POSIX 记录锁历史上与进程绑定：关任意 fd 可能释放该进程对该 inode 的全部锁——这是著名陷阱。Linux OFD 锁跟打开文件描述走，更接近「这个 fd」。强制锁（mandatory）需挂载选项与模式位，今日少用。缺口：锁等待、死锁检测（部分内核做）、NFS 上的 NLM/v4 lock。</p><p><span class="marginnote"><code>LOCK_EX</code> 的 flock 与 fcntl 锁在 Linux 上曾不互通，后有统一。教学上把它们当成可能分裂的名字空间，查清再混用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>fcntl(F_SETLKW)</code>：VFS 在 inode 的锁列表上排队，冲突则睡眠。fork 不继承 POSIX 记录锁；dup 共享。释放：显式 <code>F_UNLCK</code> 或按上述规则随 fd/进程走。NFS：锁要到服务器登记，租约到期可能丢。对照互斥原语主干课：文件锁可跨进程、可按字节范围，但不保护内存里的其它结构。</p>',8)),(a(),d(f,null,{default:t(()=>[s(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E8%BF%9B%E7%A8%8B%20A%20fcntl%22%5D%20--%3E%20LIST%5B%22inode%20%E9%94%81%E5%88%97%E8%A1%A8%22%5D%0A%20%20P2%5B%22%E8%BF%9B%E7%A8%8B%20B%22%5D%20--%3E%20LIST%0A%20%20LIST%20--%3E%7C%22%E5%86%B2%E7%AA%81%22%7C%20SLEEP%5B%22%E7%9D%A1%E7%9C%A0%E6%88%96%20EAGAIN%22%5D%0A%20%20LIST%20--%3E%7C%22%E5%85%BC%E5%AE%B9%22%7C%20OK%5B%22%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>文件锁把「文件是共享字节数组」补上自愿互斥。数据库常绕过它自己做 WAL 锁；编辑器用它或用锁文件。不要把强制锁当默认安全网：TOCTOU 与网络 FS 上不可靠。与 <a href="/cs/fs-mmap-coherence">mmap</a>：锁不自动覆盖映射写，除非应用自己锁。</p><p>死锁：同一进程对重叠区间升级锁可能自死锁，POSIX 允许检测返回 EDEADLK。</p><p>实现上：关闭任意 fd 释放该进程 POSIX 记录锁，是历史包袱，OFD 锁才跟打开文件走。NFS 上锁是租约，网络分区后可能丢，应用必须能重建。 读法上只引用<a href="/cs/nfs-semantics">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>文件锁</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>flock</code> 在 <code>open</code> 文件与 <code>LOCK_NB</code> 的全部组合测试。不保证 Windows 强制锁与 POSIX 一一对应——对照课在 NT 后课。下一课从「互斥写」转到「谁改了树」的通知：inotify。</p><p>版本字段会变，课序钉的是机制对象「文件锁」，不是某一主线内核的结构体名。 后课默认：文件上可以有自愿范围锁。目录与 inode 事件如何推给用户态，下一课 inotify。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>flock/fcntl 主要是建议锁；强制锁少用。</li><li>POSIX 记录锁与进程绑定，OFD 跟打开描述。</li><li>目录事件通知是下一课。</li><li>出处：POSIX；Linux <code>fcntl(2)</code>；McKusick；NFS 锁协议概述。</li></ul>',11))])}const P=i(p,[["render",h]]);export{k as __pageData,P as default};
